package ru.serg.slogi;

/** Canonical parameters and explanation of the current custom duel. */
public final class Rules {
    private Rules() {}
    public static final String VERSION="Словобой · уровни RC3 / RC5";
    public static final int MATCH_SECONDS=90, START_HP=30;
    public static final int START_HAND=6, HAND_LIMIT=12, DRAW_COUNT=1;
    public static final int DRAW_SECONDS=10, BOT_SECONDS=2, DEALER_SECONDS=6, EXCHANGE_HOLD_SECONDS=6;
    public static final int START_COUNTDOWN_SECONDS=2;
    public static int drawSecondsForRound(int round) {return DRAW_SECONDS-Math.min(DRAW_SECONDS-1,Math.max(1,round)-1);}
        public static int damageForLength(int syllables) {
        if(syllables==2) return 1;
        if(syllables==3) return 3;
        if(syllables==4) return 5;
        throw new IllegalArgumentException("Invalid word length");
    }
    public static final String DURATION="1:30";
    public static final String GOAL="Соберите слово целиком — сразу ударите соперника";
    public static final String TEXT=VERSION+"\n\n"
        +"ЦЕЛЬ\nУ каждого "+START_HP+" HP. Снимите здоровье соперника до нуля. Раунд длится "+DURATION+". По таймеру показывается «Результат N раунда!», можно продолжить с теми же HP, словами и фишками, начать новую дуэль или выйти. Победа и поражение — только при нулевых HP, с номером раунда.\n\n"
        +"СТАРТ\nПеред новой дуэлью — «Подбираем соперника...» и отсчёт 2 → 1. Затем раунд начинается сам. Это офлайн-дуэль с компьютерным соперником. Отсчёт не тратит время раунда и останавливается в фоне. При продолжении начатой партии или следующего раунда повторного подбора нет.\n\n"
        +"СЛОВА И УДАРЫ\nВыберите фишку и пустой слот в любом порядке. Проверка после попытки: совпало — слот заполняется, иначе «Не подходит», фишка остаётся в руке. Подсказок правильного ответа нет. Заполните слово целиком: 2 слога наносят 1 HP, 3 — 3 HP, 4 — 5 HP. Слово тратится и заменяется новым той же длины. Частичное заполнение и замена слова урона не наносят. Постоянных атак нет.\n\n"
        +"УРОВНИ\nПервый уровень: 36 исходных слов RC3, наборы из шести карточек, раздача каждые 10 секунд во всех раундах. Второй: 360 слов RC5, в том числе редкие. Новые слова вероятнее, повторы возможны; общий слог повышает вес карточки. Раздача 10/9/8/.../1 с по раундам. В исторических словарях есть слоги из одной буквы. Это авторское игровое разбиение. В начале 6 фишек, включая короткое слово. Лимит руки с предложением — 12. Между раундами новая стартовая рука не выдаётся.\n\n"
        +"ПЕРЕНОС И СБРОС\nУберите выбор фишки и нажмите заполненный слот незаконченного слова: фишка вернётся в руку, если есть место. Затем её можно поставить в другое слово. После удара потраченные фишки не возвращаются. Чтобы сбросить ненужную фишку без компенсации, удерживайте её и подтвердите в окне. Можно оставить её или попробовать обменять.\n\n"
        +"СЛЕПОЙ ОБМЕН\nВыберите фишку и нажмите «Обменять». Когда оба готовы, предложения сразу меняются вслепую. До этого свою фишку можно забрать. Очереди ходов нет. Рука соперника, его предложение и мешок скрыты; виден прогресс на карточках и готовность к обмену.\n\n"
        +"ЗАМЕНИТЬ СЛОВО\nНажмите «Заменить слово» и выберите карточку. По одному слову каждому меняется только при двух заявках. Длина сохраняется, выложенные слоги возвращаются в руку до лимита, лишние сбрасываются. Повторный выбор отменяет заявку. Если заявленное слово успели собрать, заявка на него отменяется.\n\n"
        +"ПАУЗА И СОХРАНЕНИЕ\nСоперник играет по тем же правилам, действует раз в "+BOT_SECONDS+" секунды и рассматривает замену раз в "+DEALER_SECONDS+" секунд. Сразу полученную в обмен фишку он не предлагает обратно "+EXCHANGE_HOLD_SECONDS+" секунд общего времени дуэли. Фон, пауза, диалоги и результат останавливают игру. После возврата нажмите «Продолжить дуэль». Сохранение локальное. Новая дуэль доступна в меню паузы и на результате.\n\n"
        +"ЗВУК\nКороткие звуки сопровождают действия и результат. Кнопка «Звук» открывает переключатель и громкость 0–100%. По умолчанию 100%, обе настройки сохраняются. В фоне звуки останавливаются.";
}
